package io.floci.aws.core.common;

import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;

import java.io.IOException;
import java.io.InputStream;
import java.util.LinkedHashMap;
import java.util.LinkedHashSet;
import java.util.Map;
import java.util.Set;

/**
 * The API versions and the operations of every Query service Floci serves, read once from the
 * vendored {@code aws/query-services.json}. {@link AwsQueryController} routes a request that arrives
 * without a usable credential scope by them.
 *
 * <p>The file is generated by {@code tools/aws/regen_query_services.py} from botocore's service
 * models, so a service holds every operation its model defines, implemented here or not, and the
 * versions its clients declare. {@code make aws-data-check} fails when it is stale against the
 * pinned botocore.
 *
 * <p>A missing or malformed resource is a build defect, not a runtime condition, so loading fails
 * with {@link IllegalStateException} rather than degrading to no services, which would route every
 * request without a credential scope to SQS.
 */
final class QueryServiceModels {

    static final String RESOURCE_NAME = "aws/query-services.json";

    /** One service's API versions and the operations its models define. */
    record ServiceModel(Set<String> apiVersions, Set<String> operations) {
    }

    private static final ObjectMapper MAPPER = new ObjectMapper();

    private static final Map<String, ServiceModel> SERVICES = VendoredResources.read(RESOURCE_NAME,
            "Query service models", QueryServiceModels::parse);

    private QueryServiceModels() {
    }

    /** The model of {@code service}, as the credential scope names it. */
    static ServiceModel of(String service) {
        ServiceModel model = SERVICES.get(service);
        if (model == null) {
            throw new IllegalStateException(RESOURCE_NAME + " has no service " + service);
        }
        return model;
    }

    /** The file's services, keyed by the name the credential scope uses. */
    static Map<String, ServiceModel> parse(InputStream in) throws IOException {
        JsonNode services = MAPPER.readTree(in).path("services");
        if (!services.isObject() || services.isEmpty()) {
            throw new IllegalStateException(RESOURCE_NAME + " carries no services");
        }
        Map<String, ServiceModel> models = new LinkedHashMap<>();
        services.properties().forEach(service -> models.put(service.getKey(), new ServiceModel(
                names(service.getKey(), "apiVersions", service.getValue()),
                names(service.getKey(), "operations", service.getValue()))));
        return Map.copyOf(models);
    }

    private static Set<String> names(String service, String field, JsonNode model) {
        JsonNode array = model.path(field);
        if (!array.isArray() || array.isEmpty()) {
            throw new IllegalStateException(RESOURCE_NAME + " has no " + field + " for " + service);
        }
        Set<String> names = new LinkedHashSet<>();
        array.forEach(name -> names.add(name.asText()));
        return Set.copyOf(names);
    }
}
